import{_ as n,q as a,o as l,c as d,b as e,k as o,j as s,y as h,m as c}from"./chunks/framework.D3-xQjZb.js";const I=JSON.parse('{"title":"Life Tracker · How I follow through with AI","description":"Use a private GitHub issue to give an AI-assisted task an owner, a next action, and a clear finish. Includes a worked example and a downloadable template.","frontmatter":{"title":"Life Tracker · How I follow through with AI","description":"Use a private GitHub issue to give an AI-assisted task an owner, a next action, and a clear finish. Includes a worked example and a downloadable template.","teaser":"An assistant can draft a booking request in seconds. Knowing whether you have a room takes a different check. Here’s the small system I use to follow through.","layout":"doc"},"headers":[],"relativePath":"life-tracker.md","filePath":"life-tracker.md"}'),u={name:"life-tracker.md"};function p(w,t,f,m,k,g){const r=a("ArticleHeader"),i=a("ReaderTable");return l(),d("div",null,[t[1]||(t[1]=e("h1",{id:"life-tracker",tabindex:"-1"},[o("Life Tracker "),e("a",{class:"header-anchor",href:"#life-tracker","aria-label":'Permalink to "Life Tracker"'},"​")],-1)),s(r),t[2]||(t[2]=e("p",null,"Suppose Maya is organizing a workshop. An assistant has found a room and drafted the request. Maya has an invitation ready to send. Can she put the room number on it? This booking is fictional, but it illustrates a problem I encounter whenever an assistant can draft something faster than I can verify the result.",-1)),t[3]||(t[3]=e("h2",{id:"example",tabindex:"-1"},[o("A simple example "),e("a",{class:"header-anchor",href:"#example","aria-label":'Permalink to "A simple example {#example}"'},"​")],-1)),s(i,{label:"Table: A simple example"},{default:h(()=>[...t[0]||(t[0]=[e("table",null,[e("thead",null,[e("tr",null,[e("th",null,"Booking stage"),e("th",null,"What Maya records in the issue")])]),e("tbody",null,[e("tr",null,[e("td",null,"Research"),e("td",null,"The venue lists a room with enough seats. Maya checks the availability and keeps a reference to the listing.")]),e("tr",null,[e("td",null,"Draft and decision"),e("td",null,"The assistant drafts a request with the room, date, and time. Maya checks the details and approves the request.")]),e("tr",null,[e("td",null,"In progress"),e("td",null,"Maya sends the approved request. The sent message establishes that the venue has been asked.")]),e("tr",null,[e("td",null,"Waiting"),e("td",null,"Maya owns the follow-up. She records when she will check for a reply and leaves the issue open.")]),e("tr",null,[e("td",null,"Closed"),e("td",null,"The venue confirms the room, date, and time. Maya compares the reply with the request, records where to find it, and puts the room on the invitation.")])])],-1)])]),_:1}),t[4]||(t[4]=c('<p>I call this way of following through <em>Life Tracker</em>. A private GitHub issue gives the next person a place to find the owner, the next action, and the evidence needed to close the task. Try the same fields with one piece of your own work.</p><div class="guide-template"><p><strong>Your first issue</strong></p><ul><li>Workstream</li><li>Verified current state, source reference, and time checked</li><li>Next action, owner, and dependencies</li><li>Confirmed deadline, with its source and time zone</li><li>Proposed follow-up, if needed</li><li>Completion criteria</li></ul></div><p><a href="/life-tracker-starter.txt">Download the checklist and issue template</a></p><nav class="guide-contents" aria-label="On this page"><ul><li><a href="#daily-workflow">How I use it</a></li><li><a href="#set-up">Set up your own</a></li><li><a href="#working-with-ai">How I work with AI</a></li><li><a href="#keep-it-private">Keep the work private</a></li></ul></nav><h2 id="daily-workflow" tabindex="-1">How I use it <a class="header-anchor" href="#daily-workflow" aria-label="Permalink to &quot;How I use it {#daily-workflow}&quot;">​</a></h2><p>I open an issue when a conversation produces a question, a decision, or a result to verify. I search open and closed issues first. If someone has already started the work, one update there can spare us a duplicate task.</p><p>Before I assign the next action, I check the most recent reply or source record. Then I write down five things.</p><ul><li><strong>Current state.</strong> What did I verify, and when?</li><li><strong>Next action.</strong> Who owns it? What can they actually do now?</li><li><strong>Source.</strong> Where can an authorized person check the facts?</li><li><strong>Timing.</strong> If there’s a deadline, what source confirms the date, time, and time zone? When should I check back?</li><li><strong>Completion criteria.</strong> What would someone have to see to call the work done?</li></ul><p>A date I choose for checking back goes in its own field. Adding it to an issue doesn’t schedule a reminder, so I set one separately if I need it. At review time, I check what needs a decision, what is due, and what is waiting on someone else. If I drop a task, I record that decision. If I close it as complete, I link or describe the result.</p><h2 id="set-up" tabindex="-1">Set up your own <a class="header-anchor" href="#set-up" aria-label="Permalink to &quot;Set up your own {#set-up}&quot;">​</a></h2><ol><li><strong>Choose one small area of work.</strong> For a first try, use an ordinary task you can safely describe. You can run the whole process on GitHub’s website.</li><li><strong>Create a private repository.</strong> Choose <strong>New repository</strong>, set visibility to <strong>Private</strong>, add a README, and leave Issues enabled. Check visibility before you add material. Keep GitHub Pages off for this workspace.</li><li><strong>Set the scope.</strong> In the README, name the work you track, who can read it, and which records belong in their original systems. A short summary and an authorized source reference are often enough.</li><li><strong>Give each open issue one status.</strong> I use <code>status:needs-research</code>, <code>status:needs-draft</code>, <code>status:needs-decision</code>, <code>status:in-progress</code>, and <code>status:waiting</code>. I add <code>workstream:project</code> when I need to group related work, and <code>priority:time-sensitive</code> when a concrete deadline warrants it.</li><li><strong>Take one task through the full cycle.</strong> Use an action as the title, assign an owner, and fill in the template. Verify the outcome and close the issue. Adjust the fields after you see what was useful.</li></ol><h2 id="working-with-ai" tabindex="-1">How I work with AI <a class="header-anchor" href="#working-with-ai" aria-label="Permalink to &quot;How I work with AI {#working-with-ai}&quot;">​</a></h2><p>I tell the assistant which outcome I need, which sources it may use, and whether I want research, a draft, or an action. I can give it read-only access for research. If I later want it to change an issue or send a message, I specify what to change or whom to contact and what commitments it may make.</p><p>A request I use as a starting point is:</p><blockquote><p>Review this task using the sources I have authorized. Tell me what you verified, what you still need, and who owns the next step. Draft any suggested message for my review. Do not send messages or change other systems.</p></blockquote><p>After an action, I check the resulting issue, message, or source record. If the assistant cannot see a source, it can identify what is missing. Anyone with authorized access should be able to pick up the task from the issue, including a person working without AI.</p><h2 id="keep-it-private" tabindex="-1">Keep the work private <a class="header-anchor" href="#keep-it-private" aria-label="Permalink to &quot;Keep the work private {#keep-it-private}&quot;">​</a></h2><p>A private repository is not automatically an approved home for workplace, student, client, or sensitive personal records. Check the rules of the organization that owns the material. Keep original records in the appropriate source system and limit access to the collaborators and apps that need it. Connect accounts through the supported sign-in flow. Never paste passwords or access tokens into an issue.</p><p>If reference copies are permitted, record the original source, date, and any redactions. Mark missing material explicitly. To show the method publicly, create a fictional example in a separate workspace. Issue titles, comments, filenames, screenshots, and Git history can all contain information someone never intended to share.</p><p><a href="/life-tracker-starter.txt">Download the starter</a> · <a href="/#projects">Explore the other projects</a></p>',20))])}const v=n(u,[["render",p]]);export{I as __pageData,v as default};
